  const area = (key, placeholder = '', required = true) => <textarea required={required} rows={4} value={form[key] ?? ''} placeholder={placeholder} onChange={e => change(key, e.target.value)} />;
  const assignmentReason = type === 'taskEdit' && !data.agents.some(a => a.id === form.agentId && a.status === 'available') ? '原负责人已释放或删除，请选择可分配的执行人员。' : '';
  const taskGoalReason = type === 'task' && !form.goalId ? '请先选择授权目标，任务必须归属于目标。' : '';
